import std.concurrent as conc
import std.io

pub type AppError = Failed(String)

pub fn main() effect io -> Result<(), AppError> {
    let r = scope timeout(30) {
        let waiter = task effect io {
            let sig = currentCancelSignal()
            if sig.isCancelled() {
                io.println("bad")
            } else {
                io.println("clean")
            }
            let _ = sig.awaitCancelled()
            io.println("woke-on-cancel")
        }
        let _ = waiter.await()
    }
    match r {
        Ok(_) => { io.println("ok") }
        Err(_) => { io.println("timedout") }
    }
    return Ok(())
}
